                    var recorded=local.Nodes[local.ResolveResourceNode(-sample.proceduralKey-1)];recorded.remaining=0;Check(local.ResolveResourceNode(-sample.proceduralKey-1)==recorded.id&&natural.Get(sample.proceduralKey)==recorded&&natural.Get(sample.proceduralKey).remaining==0&&local.Nodes.Count==depositRecords+1,mode+" claimed/depleted deposits become a single finite record and do not regenerate");
                    var restored=CivilisationRuntime.Deserialize(local.Civilisation.Serialize(),local.Civilisation.State.galaxySeed,local.Civilisation.Catalogue);Check(restored.Planet(local.Civilisation.Planet(world.definition.bodyId).body).frontierDeposits.Exists(n=>n.proceduralKey==recorded.proceduralKey&&n.remaining==0),mode+" seeded deposit identity and depletion survive a strategic save");
                }
                world.ReturnToMenu();yield return null;yield return new WaitForSeconds(.3f);Check(menu.State=="menu"&&FindAnyObjectByType<PlanetDevelopment>()==null,"Return to menu releases "+mode+" session");Check(JsonUtility.ToJson(preset)==presetState&&preset.edits==null&&preset.stampField==null,mode+" leaves the saved preset unchanged after the session");Check(Quaternion.Angle(originalSun.transform.rotation,originalRotation)<.001f&&originalSun.shadows==originalShadows,"Returning from "+mode+" restores the original menu sun orientation and shadow setting");
            }
        }
    }
}
